// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    Payer payer;

    function setUp() public {
        payer = new Payer();
        // deploy from a funded payable actor so `bank` is a payable recipient
        vm.prank(address(payer));
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 ts) public {
        // keep the timestamp in a wide admissible domain
        vm.assume(ts < 2**64);
        vm.warp(ts);

        // ticket costs exactly 10 wei
        vm.deal(address(payer), 10);
        vm.prank(address(payer));
        bool ok;
        try c.play{value: 10, gas: 100000}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok); // reference always succeeds here; exclude pathological gas edge cases

        // recompute the same on-chain random bit the contract used
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // RULE: payout happens (pot drained AND contract balance emptied) iff random == 0.
        assertTrue(
            (random == 0) == (c.pot() == 0 && address(c).balance == 0),
            "payout must occur exactly on random bit 0"
        );
    }
}

// adversarial-counterparty helper: real payable recipient for bank/player transfers
contract Payer {
    receive() external payable {}
}
